import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { roundCents } from './money.js';
import { nextInvoiceNumber } from './numbering.js';
import { isValidDate, addDays, lastDayOfMonth } from './dates.js';

/**
 * Validate discount percent is a number between 0 and 100.
 * @param {any} discountPercent
 * @returns {boolean}
 */
function isValidDiscount(discountPercent) {
  if (discountPercent === undefined || discountPercent === null) return true;
  return typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
}

/**
 * Calculate due date based on terms and issue date.
 * @param {string} issueDate - YYYY-MM-DD format
 * @param {string} terms - 'NET14', 'NET30', or 'EOM'
 * @returns {string} - YYYY-MM-DD format
 */
function calculateDueDate(issueDate, terms) {
  switch (terms) {
    case 'NET14':
      return addDays(issueDate, 14);
    case 'NET30':
      return addDays(issueDate, 30);
    case 'EOM':
      return lastDayOfMonth(issueDate);
    default:
      return null;
  }
}

/**
 * Create an invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }} invoice
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms?: string, dueDate?: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms }) {
  // Normalize and validate customer exists
  const normalizedCustomerId = normalizeId(customerId);
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  const customer = customerResult.value;

  // Validate date format and reality
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate and set terms (default to NET30)
  const resolvedTerms = terms ?? 'NET30';
  if (!['NET14', 'NET30', 'EOM'].includes(resolvedTerms)) return fail('TERMS_INVALID');

  const dueDate = calculateDueDate(issueDate, resolvedTerms);

  // Validate lines is not empty
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Validate and enrich each line
  const enrichedLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Validate discount
    if (!isValidDiscount(line.discountPercent)) return fail('DISCOUNT_INVALID');

    // Get product
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    const discount = line.discountPercent !== undefined ? line.discountPercent : TIER_DISCOUNTS[customer.tier];
    enrichedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: discount,
    });
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    lines: enrichedLines,
    terms: resolvedTerms,
    dueDate,
  });
}

/**
 * Calculate the total amount (before VAT) for a line.
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number} total in cents
 */
export function lineTotal(line) {
  return roundCents(line.qty * line.unitPrice);
}

/**
 * Calculate the discount amount for a line.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number} discount in cents
 */
export function lineDiscount(line) {
  const total = lineTotal(line);
  const discountPercent = line.discountPercent ?? 0;
  const discountAmount = roundCents(total * discountPercent / 100);
  return Math.max(0, discountAmount);
}

/**
 * Calculate the VAT amount for a line.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }} line
 * @returns {number} VAT in cents
 */
export function lineVAT(line) {
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const amountAfterDiscount = Math.max(0, total - discount);
  const vatRate = line.vatRate ?? 0;
  const vatAmount = roundCents(amountAfterDiscount * vatRate / 100);
  return Math.max(0, vatAmount);
}

/**
 * Calculate subtotal, discount, VAT, voucher and total for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }>, voucher?: { code: string, amount: number } }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }}
 */
export function invoiceTotals(invoice) {
  let subtotal = 0;
  let discount = 0;
  let vat = 0;
  for (const line of invoice.lines) {
    subtotal += lineTotal(line);
    discount += lineDiscount(line);
    vat += lineVAT(line);
  }
  subtotal = roundCents(subtotal);
  discount = roundCents(discount);
  vat = roundCents(vat);
  const voucher = invoice.voucher ? invoice.voucher.amount : 0;
  const total = Math.max(0, roundCents(subtotal - discount + vat - voucher));
  return {
    subtotal,
    discount,
    vat,
    voucher,
    total,
  };
}

/**
 * Add or increase a line on an invoice.
 * @param {{ status: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }> }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} line
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');
  if (!isValidDiscount(discountPercent)) return fail('DISCOUNT_INVALID');

  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;
  const newLines = [];
  let found = false;

  for (const line of invoice.lines) {
    if (line.sku === sku) {
      found = true;
      newLines.push({
        sku: line.sku,
        name: line.name,
        qty: line.qty + qty,
        unitPrice: line.unitPrice,
        vatRate: line.vatRate,
        discountPercent: discountPercent ?? line.discountPercent,
      });
    } else {
      newLines.push({ ...line });
    }
  }

  if (!found) {
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: discountPercent ?? 0,
    });
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice.
 * @param {{ status: string, lines: Array<{ sku: string }> }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  if (newLines.length === invoice.lines.length) return fail('LINE_NOT_FOUND');
  if (newLines.length === 0) return fail('NO_LINES');

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue an invoice (change status from draft to issued and assign a number).
 * @param {{ status: string }} invoice
 * @param {string[]} existingNumbers
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

/**
 * Apply a voucher to a draft invoice.
 * @param {{ status: string, voucher?: object }} invoice
 * @param {{ code: string, amount: number }} voucher
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function applyVoucher(invoice, { code, amount }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (invoice.voucher) return fail('VOUCHER_EXISTS');

  if (!Number.isInteger(amount) || amount <= 0) return fail('AMOUNT_INVALID');

  return ok({
    ...invoice,
    voucher: { code, amount },
  });
}

